def w_fig():
    x0=34;cw=34;o=T(170,13,'разряд салмағы (2ⁱ, i оңнан солға: 7…0)','t-s mu')
    ws=[128,64,32,16,8,4,2,1];bits='00011001'
    for i,(w,b) in enumerate(zip(ws,bits)):
        o+=R(x0+i*cw,20,cw,26,'soft',2)+T(x0+i*cw+cw/2,38,str(w),'t-s')
        o+=R(x0+i*cw,56,cw,26,'bxa' if b=='1' else 'bx',2)+T(x0+i*cw+cw/2,74,b,'t-b')
    o+=T(51,100,'үлкен разряд','t-s mu')+T(289,100,'кіші разряд','t-s mu')+T(170,128,'16 + 8 + 1 = 25','t-b')
    return o
f_w=F(S(340,138,w_fig(),'00011001 екілік санының разрядтары'),'Бірлер тұрған разрядтардың салмағын қосамыз: 00011001₂ = 25')

def hex_fig():
    o='';bits='10100101'
    for g in range(2):
        gx=40+g*140
        for k in range(4):
            o+=R(gx+k*30,14,30,26,'bxa' if g==0 else 'bx',2)+T(gx+k*30+15,32,bits[g*4+k],'t-b')
        o+=L(gx,48,gx+120,48)+A(gx+60,48,gx+60,70)
    o+=R(75,74,50,28,'bxa')+T(100,93,'A','t-b')+R(215,74,50,28,'bx')+T(240,93,'5','t-b')
    o+=T(100,116,'1010 = 10','t-s mu')+T(240,116,'0101 = 5','t-s mu')+T(170,142,'0xA5 = 10·16 + 5 = 165','t-b')
    return o
f_hex=F(S(340,152,hex_fig(),'Байттың екі тетрадасы және HEX цифрлары'),'Байт екі тетрадаға бөлінеді, әр тетрада — бір HEX цифр')

